{"version":3,"file":"RequestDetail.jsdbx","sources":["../../src/client/components/RequestDetail.tsx"],"sourcesContent":["import React, { useState, useEffect } from "react";
import { fetchRequest } from "../services/api";

interface Props {
  recordId: string;
  navigateToView: (v: string, id?: string | null, o?: { title?: string }) => void;
}

const d = (f: any) => f?.display_value || f || "";

const FIELDS = [
  { key: "number", label: "Number" },
  { key: "state", label: "State" },
  { key: "visit_type", label: "Visit Type" },
  { key: "purpose", label: "Purpose of Visit" },
  { key: "scheduled_start", label: "Scheduled Start" },
  { key: "scheduled_end", label: "Scheduled End" },
  { key: "host_employee", label: "Host Employee" },
  { key: "expected_visitors", label: "Expected Visitors" },
  { key: "external_request", label: "External Request" },
  { key: "personal_devices_permitted", label: "Personal Devices Permitted" },
  { key: "photography_permitted", label: "Photography Permitted" },
];

export default function RequestDetail({ recordId, navigateToView }: Props) {
  const [record, setRecord] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchRequest(recordId).then(setRecord).catch(e => setError(e.message)).finally(() => setLoading(false));
  }, [recordId]);

  if (loading) return <div className="portal-loading"><div className="portal-loading__spinner" /><p className="portal-loading__text">Loading request...</p></div>;
  if (error) return <div className="form-error">{error}</div>;
  if (!record) return <div className="form-error">Record not found</div>;

  return (
    <div className="request-detail">
      <div className="request-detail__header">
        <a href="?view=requests" className="nav-btn nav-btn--back" onClick={e => { e.preventDefault(); navigateToView("requests", null, { title: "My Access Requests" }); }}>← Back to Requests</a>
        <h2 className="request-detail__title">Request {d(record.number)}</h2>
      </div>
      <div className="detail-card">
        {FIELDS.map(f => {
          const val = d(record[f.key]);
          if (!val) return null;
          return (
            <div key={f.key} className="detail-row">
              <span className="detail-row__label">{f.label}</span>
              <span className="detail-row__value">{val === "true" ? "Yes" : val === "false" ? "No" : val}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
"],"names":["d","f","display_value","FIELDS","key","label","RequestDetail","recordId","navigateToView","record","setRecord","useState","loading","setLoading","error","setError","useEffect","fetchRequest","then","catch","e","message","finally","_jsxs","div","className","_jsx","p","children","a","href","onClick","preventDefault","title","h2","number","map","val","span"],"mappings":"sJAQA,CAAMA,CAAAA,CAAAA,CAAAA,CAAAA,CAAI,CAAYC,CAAAA,CAAAA,CAAAA,CAAAA,CAAGC,eAAiBD,CAAK,CAAA,CAAA,CAAA,CAAA,CAEzCE,OAAS,CACb,CAAEC,CAAK,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAUC,MAAO,CAAS,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CACjC,CAAED,CAAAA,CAAAA,CAAAA,CAAK,QAASC,CAAO,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAQ,CAC/B,CAAA,CAAED,IAAK,CAAcC,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAO,YAAa,CACzC,CAAA,CAAED,IAAK,CAAWC,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAO,CAAmB,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAC5C,CAAED,CAAK,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAmBC,CAAO,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAkB,EACnD,CAAED,CAAAA,CAAAA,CAAAA,CAAK,CAAiBC,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAO,eAAgB,CAC/C,CAAA,CAAED,IAAK,CAAiBC,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAO,eAAgB,CAC/C,CAAA,CAAED,CAAK,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAqBC,MAAO,CAAoB,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CACvD,CAAED,CAAK,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,